#!/usr/bin/env python3
import hashlib, html, io, json, runpy, time, urllib.parse, urllib.request
from pathlib import Path
from PIL import Image
base=runpy.run_path(str(Path(__file__).with_name('publish_recipe_20260825_1000.py')),run_name='recipe_base')
TITLE='Arroz Cremoso com Frango e Legumes para Bebê: Almoço Fácil'; SLUG_KEY='arroz-cremoso-frango-legumes-bebe'; CLUSTER='Cluster 4 — Refeições com frango, carne e peixe'; KEYWORD='arroz cremoso com frango e legumes para bebê'
MARKER=base['MARKER']; BLOG_ID=base['BLOG_ID']; COVER_DIR=base['COVER_DIR']; RAW_BASE=base['RAW_BASE']; LOG_PATH=base['LOG_PATH']; RESULT_PATH=base['RESULT_PATH']; W,H=1200,630

def generate_cover(path):
 p="Photorealistic horizontal food photograph of the finished Brazilian baby-friendly recipe 'Arroz Cremoso com Frango e Legumes para Bebê': very soft moist cooked rice with finely shredded well-cooked chicken, tiny tender carrot and zucchini pieces, thick spoonable creamy texture made from the cooking moisture, not soup, served in a small shallow matte ceramic bowl. Warm natural morning window light, light wood table, simple neutral linen, three-quarter editorial food photography, realistic homemade texture and imperfections. No cream sauce, cheese, packaged food, baby, child, people, hands, text, logo, watermark, collage, illustration or cartoon."
 enc=urllib.parse.quote(p,safe=''); seed=int(hashlib.sha256(TITLE.encode()).hexdigest()[:12],16)%2147483647; last=None
 for a in range(8):
  try:
   u=f'https://image.pollinations.ai/prompt/{enc}?width={W}&height={H}&model=flux&nologo=true&safe=true&enhance=true&seed={seed+a*10007}'; req=urllib.request.Request(u,headers={'User-Agent':'Mozilla/5.0 (compatible; ReceitasParaPequenos/3.0)','Accept':'image/*'})
   with urllib.request.urlopen(req,timeout=240) as r: raw=r.read()
   if len(raw)<15000: raise RuntimeError('small image response')
   im=Image.open(io.BytesIO(raw)).convert('RGB'); tr=W/H; cr=im.width/im.height
   if cr>tr: nw=int(im.height*tr); x=(im.width-nw)//2; im=im.crop((x,0,x+nw,im.height))
   elif cr<tr: nh=int(im.width/tr); y=(im.height-nh)//2; im=im.crop((0,y,im.width,y+nh))
   im=im.resize((W,H),Image.Resampling.LANCZOS); path.parent.mkdir(parents=True,exist_ok=True); im.save(path,'JPEG',quality=92,optimize=True,progressive=True); return
  except Exception as e: last=e; time.sleep(min(10*(a+1),45))
 raise RuntimeError(f'cover generation failed: {last}')

def article(cover):
 schema={'@context':'https://schema.org','@type':'Recipe','name':TITLE,'image':[cover],'author':{'@type':'Organization','name':'Equipe Editorial do Receitas Para Pequenos'},'description':'Arroz bem macio com frango desfiado, cenoura e abobrinha, preparado com textura úmida e adaptável.','recipeCategory':'Almoço e jantar','recipeCuisine':'Brasileira','keywords':KEYWORD+', alimentação complementar, almoço com frango','recipeYield':'2 pequenas porções','recipeIngredient':['3 colheres (sopa) de arroz cru','80 g de peito ou sobrecoxa de frango sem osso e sem pele','2 colheres (sopa) de cenoura ralada fina','2 colheres (sopa) de abobrinha ralada','1 colher (sopa) de cebola bem picada','Água suficiente para o cozimento'],'recipeInstructions':[{'@type':'HowToStep','text':'Cozinhe o frango completamente e desfie bem fino.'},{'@type':'HowToStep','text':'Cozinhe arroz, cebola, cenoura e água até o arroz ficar muito macio.'},{'@type':'HowToStep','text':'Junte a abobrinha e o frango desfiado e cozinhe até tudo ficar macio e úmido.'},{'@type':'HowToStep','text':'Amasse levemente com o garfo e adapte a textura às habilidades da criança.'}]}
 sj=json.dumps(schema,ensure_ascii=False).replace('</','<\\/'); alt=html.escape(TITLE,quote=True)
 return f"""{MARKER}<div class='separator' style='clear:both;margin:0 0 24px;text-align:center'><img alt='{alt}' data-original-height='630' data-original-width='1200' src='{cover}' style='border-radius:14px;height:auto;max-width:100%;width:1200px'/></div><p><strong>Por Equipe Editorial do Receitas Para Pequenos</strong></p><p>Este arroz cremoso com frango e legumes é uma opção prática para almoço ou jantar: o arroz cozinha até ficar bem macio, enquanto o frango desfiado, a cenoura e a abobrinha entram em pedaços pequenos e tenros. A cremosidade vem da própria água do cozimento, sem precisar de creme ou molho pronto.</p><p><strong>Atenção:</strong> adapte a consistência e o tamanho dos pedaços às habilidades da criança e ofereça sempre com ela sentada e supervisionada. Alergias, dificuldades de mastigação/deglutição e necessidades especiais exigem orientação profissional individualizada.</p><h2>Ingredientes</h2><ul><li>3 colheres (sopa) de arroz cru</li><li>80 g de peito ou sobrecoxa de frango sem osso e sem pele</li><li>2 colheres (sopa) de cenoura ralada fina</li><li>2 colheres (sopa) de abobrinha ralada</li><li>1 colher (sopa) de cebola bem picada</li><li>Água suficiente para o cozimento</li></ul><h2>Modo de preparo</h2><ol><li>Cozinhe o frango completamente em água. Depois, desfie bem fino e reserve.</li><li>Em uma panela pequena, coloque arroz, cebola e cenoura. Cubra com água e cozinhe em fogo baixo, mexendo de vez em quando.</li><li>Quando o arroz estiver quase desmanchando, acrescente a abobrinha e o frango desfiado. Se necessário, junte pequenas quantidades de água.</li><li>Cozinhe até os legumes estarem muito macios e a preparação ficar úmida e espessa, sem caldo solto.</li><li>Amasse levemente com o garfo quando necessário e espere amornar antes de servir.</li></ol><h2>Como deve ficar a textura</h2><p>O arroz deve estar mais macio e úmido que um arroz soltinho comum, mas não líquido como sopa. O frango precisa estar bem desfiado e os legumes macios. O Ministério da Saúde orienta oferecer comida amassada no início da alimentação complementar e evoluir gradualmente a consistência conforme as habilidades da criança.</p><h2>Como servir e adaptar</h2><p>No começo da alimentação complementar, pressione levemente a preparação com o garfo para reduzir grumos maiores. Conforme a criança desenvolve habilidade para lidar com texturas mais marcadas, deixe o arroz menos amassado. Não é necessário bater no liquidificador.</p><h2>Substituições culinárias</h2><p>A cenoura ou a abobrinha podem ser substituídas por outro legume que cozinhe até ficar bem macio. Peito e sobrecoxa sem osso e sem pele funcionam na receita; em qualquer caso, o frango deve estar completamente cozido. Necessidades alimentares específicas devem ser avaliadas por profissional habilitado.</p><h2>Armazenamento</h2><p>Como a preparação reúne arroz e frango cozidos, prepare porções pequenas e mantenha cuidados rigorosos de higiene e conservação. Não reutilize a porção que já teve contato com a colher ou a boca da criança. Para armazenamento por tempo prolongado, siga orientações oficiais de segurança alimentar adequadas às condições de refrigeração disponíveis.</p><h2>Perguntas frequentes</h2><h3>Precisa usar creme de leite para ficar cremoso?</h3><p>Não. Cozinhar o arroz com um pouco mais de água e deixar os grãos bem macios cria uma textura úmida e cremosa sem creme de leite.</p><h3>Posso bater tudo no liquidificador?</h3><p>Não é necessário. O garfo permite adaptar a textura sem transformar a refeição em líquido e facilita a progressão gradual da consistência.</p><h3>Posso usar arroz já cozido?</h3><p>Para esta versão, começar com arroz cru facilita cozinhar todos os ingredientes até uma textura uniforme e macia. Se adaptar com arroz previamente cozido, cuide da conservação e aqueça adequadamente.</p><h2>Receitas relacionadas</h2><ul><li><a href='https://www.receitasparapequenos.site/2026/08/bolinho-de-batata-doce-e-frango-assado.html'>Bolinho de Batata-Doce e Frango Assado para Bebê</a></li><li><a href='https://www.receitasparapequenos.site/2026/08/pure-de-abobora-com-carne-para-bebe.html'>Purê de Abóbora com Carne para Bebê</a></li><li><a href='https://www.receitasparapequenos.site/2026/08/almondegas-de-carne-moida-com-legumes.html'>Almôndegas de Carne Moída com Legumes para Bebês</a></li></ul><h2>Referências oficiais</h2><ul><li><a href='https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/s/saude-da-crianca/primeira-infancia/alimentacao-saudavel' rel='nofollow'>Ministério da Saúde — Alimentação saudável na primeira infância</a></li><li><a href='https://www.gov.br/saude/pt-br/composicao/saps/promocao-da-saude/guias-alimentares/publicacoes/guia_da_crianca_2019.pdf/view' rel='nofollow'>Ministério da Saúde — Guia Alimentar para Crianças Brasileiras Menores de 2 Anos</a></li></ul><h2>Conclusão</h2><p>Com arroz bem macio, frango desfiado e legumes tenros, esta receita cria uma refeição simples cuja consistência pode evoluir junto com as habilidades da criança.</p><script type='application/ld+json'>{sj}</script>"""

def main():
 tok=base['token'](); posts=base['list_posts'](tok)
 for p in posts:
  t=(p.get('title') or '').casefold()
  if t==TITLE.casefold() or ('arroz' in t and 'frango' in t and 'legumes' in t and 'cremos' in t):
   RESULT_PATH.write_text(f'outcome=skipped_duplicate\ntitle={p.get("title","")}\nurl={p.get("url","")}\n',encoding='utf-8'); base['git_commit_push']([RESULT_PATH],'Record duplicate prevention for chicken rice'); return
 suffix=hashlib.sha1(TITLE.encode()).hexdigest()[:10]; cp=COVER_DIR/f'{SLUG_KEY}-{suffix}.jpg'; cu=f'{RAW_BASE}/{cp.name}'
 if not cp.exists(): generate_cover(cp); base['git_commit_push']([cp],'Add unique AI food photo for chicken rice'); time.sleep(8)
 content=article(cu)
 if MARKER not in content or cu not in content: raise RuntimeError('cover verification failed before publish')
 created=base['api'](tok,'POST',f'/blogs/{BLOG_ID}/posts',{'isDraft':'false','fetchBody':'true'},{'kind':'blogger#post','blog':{'id':BLOG_ID},'title':TITLE,'content':content,'labels':['Alimentação complementar','Almoço','Jantar','Frango','Arroz','Legumes']}); pid=str(created.get('id','')); url=created.get('url','')
 if not pid: raise RuntimeError('Blogger did not return post id')
 vc=(base['api'](tok,'GET',f'/blogs/{BLOG_ID}/posts/{pid}',{'view':'ADMIN'}).get('content') or '')
 if MARKER not in vc or cu not in vc: raise RuntimeError('live Blogger post failed cover verification')
 log=base['load_log'](); log.append({'published_at':created.get('published'),'title':TITLE,'url':url,'post_id':pid,'cluster':CLUSTER,'keyword':KEYWORD,'cover_url':cu,'marker':MARKER}); LOG_PATH.write_text(json.dumps(log,ensure_ascii=False,indent=2)+'\n',encoding='utf-8'); RESULT_PATH.write_text('outcome=success\n'+f'title={TITLE}\nurl={url}\npost_id={pid}\ncluster={CLUSTER}\ncover_url={cu}\nmarker_verified=true\n',encoding='utf-8'); base['git_commit_push']([LOG_PATH,RESULT_PATH],'Record published chicken rice recipe')
if __name__=='__main__': main()
